{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 bucket encryption is not explicitly configured",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The bucket stores flow logs but does not declare server-side encryption, leaving protection dependent on external or provider defaults."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Without versioning, flow log objects cannot be recovered after accidental overwrites or deletions."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public access protections are not configured",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The bucket has no explicit public access block, so future public ACLs or bucket policies could expose flow log data."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "S3 bucket does not enforce encrypted transport",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "No bucket policy denies requests made without TLS, allowing clients with sufficient permissions to access flow logs over insecure transport."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive bucket deletion is enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket and all retained flow logs without first requiring the bucket to be emptied."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.flowbucket.arn,
          "${aws_s3_bucket.flowbucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}
",
  "fix_summary": "Enabled explicit server-side encryption, versioning, comprehensive public access blocking, and TLS-only access. Disabled forceful deletion to reduce the risk of destroying retained flow logs."
}
